// The examples pin down only four points on this curve:
//   2 types -> 2, 3 types -> 2, 5 types -> 3, 6 types -> 5.
// Up to three types the score is flat at 2. From five types on, each further
// type is worth 2 more, so that band is a line of slope 2 through (5, 3).
//
// NOTE: those two bands do not meet. Extrapolating the slope-2 line back to
// four types yields 1, i.e. a fourth monster type LOWERS the Sphinx score from
// 2 to 1. No example covers four types, so this is unverified and preserved
// here only to keep behaviour unchanged. See the note in the summary.
const TYPE_THRESHOLD = 3;
const POINTS_PER_TYPE_BEYOND_THRESHOLD = 2;

// "Sphinx — 1 point. 2 per type beyond three, else 1." The types counted are
// those among the rest of the army: every card except the scoring Sphinx
// itself (a second Sphinx does count, as one type).
const scoreOneSphinx = (rest: Card[]): number => {
  const typeCount = countDistinctTypes(rest);
  const bonus =
    typeCount > TYPE_THRESHOLD
      ? POINTS_PER_TYPE_BEYOND_THRESHOLD * (typeCount - TYPE_THRESHOLD)
      : 1;
  return 1 + bonus;
};

export const sphinxScore = (army: Card[]): number =>
  army.reduce(
    (score, card, index) =>
      isSphinx(card)
        ? score + scoreOneSphinx(army.filter((_, other) => other !== index))
        : score,
    0,
  );

