cat > /tmp/equiv.ts <<'EOF'
import { sphinxScore } from "./src/sphinx-score.js";
type Card = { monster: string; rank?: number };
const isSphinx = (c: Card) => c.monster === "sphinx";
const distinct = (a: Card[]) => new Set(a.map((c) => c.monster)).size;
const oldOne = (rest: Card[]) => {
  const t = distinct(rest);
  return 1 + (t > 3 ? 2 * (t - 3) : 1);
};
const oldScore = (army: Card[]) =>
  army.reduce((s, card, i) =>
    isSphinx(card) ? s + oldOne(army.filter((_, o) => o !== i)) : s, 0);

const pool = ["sphinx","chimera","orthrus","zombie","hydra","cyclops","undead-warrior"];
let checked = 0, bad = 0;
for (let n = 0; n <= 6; n++) {
  const idx = new Array(n).fill(0);
  while (true) {
    const army = idx.map((k) => ({ monster: pool[k] }));
    const a = oldScore(army), b = sphinxScore(army);
    checked++;
    if (a !== b) { bad++; if (bad <= 5) console.log("MISMATCH", JSON.stringify(army.map(c=>c.monster)), "old:", a, "new:", b); }
    let p = n - 1;
    while (p >= 0 && idx[p] === pool.length - 1) { idx[p] = 0; p--; }
    if (p < 0) break;
    idx[p]++;
  }
}
console.log(`checked ${checked} armies, ${bad} mismatches`);
EOF
